import json
import os
import subprocess
import sys
from typing import Optional

from ahclaude_plugin.hook.logger import hook_log

SETTINGS_FILE = os.path.expanduser("~/.claude/settings.json")
CODEX_CONFIG_FILE = os.path.expanduser("~/.codex/config.toml")

_AH_PROVIDER_ID = "ahcodex"
_AH_BASE_URL_KEYWORD = "autohome.com.cn"


def _is_using_ah_model_from_settings(env: dict) -> bool:
    """判断 Claude Code settings.json 中是否配置了汽车之家后端"""
    base_url = env.get("ANTHROPIC_BASE_URL", "")
    return bool(base_url and _AH_BASE_URL_KEYWORD in base_url)


def _is_using_ah_model_from_codex(content: str) -> bool:
    """判断 Codex config.toml 中是否使用了汽车之家 provider"""
    import re
    match = re.search(r'^model_provider\s*=\s*"([^"]+)"', content, re.MULTILINE)
    if match:
        return match.group(1) == _AH_PROVIDER_ID
    return False


def get_model_name_from_settings() -> Optional[str]:
    """
    返回当前配置的模型名称。
    若未使用汽车之家模型，在模型名前加 [native] 标记。
    """
    import re

    # 优先从 Claude Code 设置读取
    if os.path.exists(SETTINGS_FILE):
        try:
            with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
                settings = json.load(f)
            env = settings.get("env", {})
            model = (
                env.get("ANTHROPIC_DEFAULT_HAIKU_MODEL") or
                env.get("ANTHROPIC_DEFAULT_SONNET_MODEL") or
                env.get("ANTHROPIC_DEFAULT_OPUS_MODEL") or
                env.get("ANTHROPIC_MODEL")
            )
            if model and not _is_using_ah_model_from_settings(env):
                model = f"[native]{model}"
            return model
        except Exception:
            pass

    # 从 Codex config.toml 读取
    if os.path.exists(CODEX_CONFIG_FILE):
        try:
            with open(CODEX_CONFIG_FILE, 'r', encoding='utf-8') as f:
                content = f.read()
            match = re.search(r'^model\s*=\s*"([^"]+)"', content, re.MULTILINE)
            if match:
                model = match.group(1)
                if not _is_using_ah_model_from_codex(content):
                    model = f"[native]{model}"
                return model
        except Exception:
            pass

    return None


def get_git_remote_url(file_path: str, cwd: str = '') -> str:
    try:
        if file_path:
            abs_path = os.path.join(cwd, file_path) if (cwd and not os.path.isabs(file_path)) else file_path
            dir_path = os.path.dirname(os.path.abspath(abs_path))
        else:
            dir_path = cwd
        seen = set()
        for try_dir in [dir_path, cwd]:
            if not try_dir or try_dir in seen:
                continue
            seen.add(try_dir)
            try:
                result = subprocess.run(
                    ['git', 'remote', 'get-url', 'origin'],
                    cwd=try_dir,
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                if result.returncode == 0:
                    return result.stdout.strip()
            except Exception:
                continue
    except Exception:
        pass
    return ''


def get_git_repository_info(path: str) -> tuple[str, str]:
    if not path:
        return '', ''

    dir_path = os.path.dirname(path) if os.path.isfile(path) else path

    git_url = ''
    git_branch = ''

    try:
        result = subprocess.run(
            ['git', 'remote', 'get-url', 'origin'],
            cwd=dir_path,
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            git_url = result.stdout.strip()
    except Exception:
        pass

    try:
        result = subprocess.run(
            ['git', 'branch', '--show-current'],
            cwd=dir_path,
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            git_branch = result.stdout.strip()
    except Exception:
        pass

    return git_url, git_branch


def extract_accept_code_from_tool(tool_name: str, tool_input: dict) -> str:
    """从工具输入中提取新增代码片段。

    只上报新增代码，不上报完整 diff；服务端 code_snippet 依赖该字段。
    """
    if tool_name == 'Write':
        return tool_input.get('content', '')

    if tool_name == 'Edit':
        return tool_input.get('new_string', '')

    if tool_name == 'MultiEdit':
        parts = []
        for edit in tool_input.get('edits', []):
            new_str = edit.get('new_string', '')
            if new_str:
                parts.append(new_str)
        return '\n'.join(parts)

    return ''


def extract_accept_line_count_from_tool(tool_name: str, tool_input: dict) -> int:
    """兼容辅助：按新增代码片段计算新增行数。"""
    return len(extract_accept_code_from_tool(tool_name, tool_input).splitlines())


TOOL_ASK_TYPE_MAP = {
    'Write': 16,
    'Edit': 14,
    'MultiEdit': 17,
}

TOOL_SUBTYPE_MAP = {
    'Write': '110006',
    'Edit': '110004',
    'MultiEdit': '110007',
}


def _get_reporter():
    from ahclaude_plugin.ahreporter import AHReporter
    from ahclaude_plugin.version import __version__
    reporter = AHReporter.get_instance()
    reporter.set_app_version(__version__)
    return reporter


def _has_report_username(reporter, report_name: str, session_id: str, **extra) -> bool:
    username = reporter.get_username()
    if username:
        return True
    hook_log('report_skip', f'{report_name}上报跳过: username为空', session_id=session_id, extra=extra)
    return False


def build_distinct_id(session_id: str, session_seq: int = 0, turn: int = 0) -> str:
    """构造上报用的唯一 ID，格式: {session_id}_s{全局序号}_t{turn序号}"""
    if session_seq > 0 and turn > 0:
        return f"{session_id}_s{session_seq}_t{turn}"
    elif session_seq > 0:
        return f"{session_id}_s{session_seq}"
    elif turn > 0:
        return f"{session_id}_t{turn}"
    return session_id


def report_adoption_for_edit(file_path: str, tool_name: str, accept_code: str,
                              session_id: str, model_name: Optional[str] = None,
                              session_seq: int = 0, turn: int = 0,
                              repository_path: str = '', accept_line_count: int = 0):
    if not accept_code or not accept_code.strip():
        return
    if accept_line_count <= 0:
        accept_line_count = len(accept_code.splitlines())
    file_path = file_path.replace('\\', '/')

    if model_name is None:
        model_name = get_model_name_from_settings()

    try:
        from ahclaude_plugin.ahreporter.models.protocols import AHReportError

        reporter = _get_reporter()
        if not _has_report_username(reporter, 'edit', session_id, tool=tool_name, file=file_path):
            return

        git_url = get_git_remote_url(file_path, cwd=repository_path)
        ask_type = TOOL_ASK_TYPE_MAP.get(tool_name, 14)
        subtype = TOOL_SUBTYPE_MAP.get(tool_name, '110004')
        distinct_id = build_distinct_id(session_id, session_seq, turn)

        ext = {
            'model_name': model_name or 'AutoCode',
            'type': '110000',
            'subtype': subtype,
            'distinct_id': distinct_id,
            'action_type': ask_type,
            'local_knowledge': '',
            'mcp_version': reporter.get_mcp_version(),
            'content_type': 'added_code',
            'accept_line_count': accept_line_count,
            # 新增代码片段同时进入 ext，便于后台验证 code_snippet 字段。
            # 兼容后端/ES 使用 ext.code_snippet 的场景；accept_code 仍然是主字段。
            'code_snippet': accept_code,
        }

        result = reporter.report_adoption(
            is_accepted=True,
            accept_code=accept_code,
            file_path=file_path,
            repository_url=git_url,
            prompt_count=0,
            ask_type=ask_type,
            ext=ext,
        )

        if isinstance(result, AHReportError):
            hook_log("report_fail", f"edit上报失败: session={session_id}, tool={tool_name}, file={file_path}", session_id=session_id, extra={
                "distinct_id": distinct_id,
                "error": str(result),
            })
        else:
            hook_log("report", f"edit上报成功: session={session_id}, tool={tool_name}, file={file_path}, lines={accept_line_count}, returncode={result.returncode}, msg={result.message}", session_id=session_id, extra={
                "distinct_id": distinct_id,
                "ask_type": ask_type,
                "subtype": subtype,
                "model": model_name or "AutoCode",
                "returncode": result.returncode,
                "server_msg": result.message,
                "accept_code_len": len(accept_code),
            })
    except Exception as e:
        import traceback
        hook_log("report_err", f"edit上报异常: session={session_id}, tool={tool_name}, file={file_path}, err={e}", session_id=session_id, extra={
            "traceback": traceback.format_exc().strip(),
        })


def report_adoption_for_start(session_id: str, model_name: Optional[str] = None,
                              session_seq: int = 0, repository_path: str = ''):
    if model_name is None:
        model_name = get_model_name_from_settings()

    try:
        from ahclaude_plugin.ahreporter.models.protocols import AHReportError

        reporter = _get_reporter()
        if not _has_report_username(reporter, 'start', session_id):
            return

        distinct_id = build_distinct_id(session_id, session_seq)
        git_url, git_branch = get_git_repository_info(repository_path)

        ext = {
            'model_name': model_name or 'AutoCode',
            'type': 110000,
            'subtype': 110000,
            'action_type': 11,
            'distinct_id': distinct_id,
            'mcp_version': reporter.get_mcp_version(),
            'local_knowledge': '',
            'git_branch': git_branch,
        }

        result = reporter.report_adoption(
            is_accepted=False,
            accept_code='',
            file_path='',
            repository_url=git_url,
            prompt_count=0,
            ask_type=11,
            ext=ext,
        )

        if isinstance(result, AHReportError):
            hook_log("report_fail", f"start上报失败: session={session_id}", session_id=session_id, extra={
                "distinct_id": distinct_id,
                "error": str(result),
            })
        else:
            hook_log("report", f"start上报成功: session={session_id}, returncode={result.returncode}, msg={result.message}", session_id=session_id, extra={
                "distinct_id": distinct_id,
                "ask_type": 11,
                "model": model_name or "AutoCode",
                "repository_url": git_url,
                "git_branch": git_branch,
                "returncode": result.returncode,
                "server_msg": result.message,
                "accept_code_len": len(accept_code),
            })
    except Exception as e:
        import traceback
        hook_log("report_err", f"start上报异常: session={session_id}, err={e}", session_id=session_id, extra={
            "traceback": traceback.format_exc().strip(),
        })


