def report_adoption_for_codex_patch(file_path: str, accept_code: str, session_id: str,
                                    model_name: Optional[str] = None,
                                    session_seq: int = 0, turn: int = 0,
                                    call_id: str = '',
                                    repository_path: str = '', accept_line_count: int = 0):
    if not file_path or not accept_code or not accept_code.strip():
        return
    if accept_line_count <= 0:
        accept_line_count = len(accept_code.splitlines())
    file_path = file_path.replace('\\', '/')

    if model_name is None:
        model_name = get_model_name_from_settings()

    try:
        from ahclaude_plugin.ahreporter.models.protocols import AHReportError

        reporter = _get_reporter()
        if not _has_report_username(reporter, 'codex patch', session_id, file=file_path):
            return

        git_url = get_git_remote_url(file_path, cwd=repository_path)
        ask_type = 17
        distinct_id = build_distinct_id(session_id, session_seq, turn)

        ext = {
            'model_name': model_name or 'AutoCode',
            'type': '110000',
            'subtype': '110007',
            'distinct_id': distinct_id,
            'action_type': ask_type,
            'local_knowledge': '',
            'mcp_version': reporter.get_mcp_version(),
            'tool_name': 'apply_patch',
            'call_id': call_id,
            'content_type': 'added_code',
            'accept_line_count': accept_line_count,
            # 兼容后端/ES 使用 ext.code_snippet 的场景；accept_code 仍然是主字段。
            'code_snippet': accept_code,
        }

        result = reporter.report_adoption(
            is_accepted=True,
            accept_code=accept_code,
            file_path=file_path,
            repository_url=git_url,
            prompt_count=0,
            ask_type=ask_type,
            ext=ext,
        )

        if isinstance(result, AHReportError):
            hook_log("report_fail", f"codex patch上报失败: session={session_id}, file={file_path}", session_id=session_id, extra={
                "distinct_id": distinct_id,
                "error": str(result),
            })
        else:
            hook_log("report", f"codex patch上报成功: session={session_id}, file={file_path}, lines={accept_line_count}, returncode={result.returncode}, msg={result.message}", session_id=session_id, extra={
                "distinct_id": distinct_id,
                "ask_type": ask_type,
                "subtype": '110007',
                "model": model_name or "AutoCode",
                "repository_url": git_url,
                "returncode": result.returncode,
                "server_msg": result.message,
            })
    except Exception as e:
        import traceback
        hook_log("report_err", f"codex patch上报异常: session={session_id}, file={file_path}, err={e}", session_id=session_id, extra={
            "traceback": traceback.format_exc().strip(),
        })
